export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function icon(name,size=20){const key=iconNodes[name]?name:'pin';return `<svg class="ico lucide lucide-${iconNames[key]}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconNodes[key].map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${v}"`).join(' ')}></${tag}>`).join('')}</svg>`}
export function Button(label,options={}){const {color='primary',variant='fill',size='large',display='inline',disabled=false,loading=false,leadingIcon,action='save'}=options;return `<button type="button" class="jy-btn" data-color="${color}" data-variant="${variant}" data-size="${size}" data-display="${display}" ${disabled||loading?'disabled':''} ${loading?'aria-busy="true"':''} data-action="${action}">${leadingIcon?icon(leadingIcon,20):''}${loading?'<span class="jy-loader small" aria-hidden="true"></span>':''}${escapeHTML(label)}</button>`}
export function Badge(label,options={}){return `<span class="jy-badge ${options.variant==='fill'?'fill':''} ${options.color||''} ${options.size==='large'?'large':''}">${escapeHTML(label)}</span>`}
export function Switch(label,{checked=true,disabled=false}={}){return `<label class="jy-switch"><input type="checkbox" role="switch" ${checked?'checked':''} ${disabled?'disabled':''}><span>${escapeHTML(label)}</span></label>`}
export function Checkbox(label,{checked=false,disabled=false,radio=false,name='demo-choice'}={}){return `<label class="jy-check"><input type="${radio?'radio':'checkbox'}" ${radio?`name="${name}"`:''} ${checked?'checked':''} ${disabled?'disabled':''}><span>${escapeHTML(label)}</span></label>`}
export function TextField(label,{placeholder='',error='',disabled=false,value=''}={}){const id='field-'+(++TextField.count);return `<div class="jy-field"><label class="jy-label" for="${id}">${escapeHTML(label)}</label><input class="jy-input" id="${id}" placeholder="${escapeHTML(placeholder)}" value="${escapeHTML(value)}" ${error?`aria-invalid="true" aria-describedby="${id}-help"`:''} ${disabled?'disabled':''}>${error?`<span class="jy-help jy-error" id="${id}-help">${escapeHTML(error)}</span>`:''}</div>`}TextField.count=0;
function listrow(title,sub,ic='pin',right=icon('arrow')){return `<button type="button" class="jy-listrow" data-action="place"><span class="jy-asset">${icon(ic,24)}</span><span class="jy-rowtext"><strong>${title}</strong><small>${sub}</small></span>${right}</button>`}
function segment(t,tab=false){return `<div class="${tab?'jy-tabs':'jy-segment'}" role="tablist" aria-label="${t.explore}">${[t.all,t.place,t.food,t.stay].map((s,i)=>`<button type="button" role="tab" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-action="select-tab">${s}</button>`).join('')}</div><p class="jy-small jy-muted" data-tab-result>${t.all}</p>`}
export function renderComponent(id,{lang='ko',variant='Basic'}={}){
 const t=strings[lang]||strings.ko;const v=variant.toLowerCase();const btn=(s,o={})=>Button(s,o);let h='';
 switch(id){
 case 'badge':if(v==='notifications'){h=`<div class="jy-notification-stage"><span class="jy-navicon">${icon('bell',32)}<span class="jy-notification dot" aria-label="${t.new}"></span></span><span class="jy-navicon">${icon('bell',32)}<span class="jy-notification" aria-label="99+ ${t.notice}">99+</span></span></div>`;break;}h=`<div class="jy-row">${Badge(t.new,{variant:v.includes('fill')?'fill':'weak',size:v.includes('size')?'large':''})}${Badge(t.available,{color:'success'})}${Badge(t.popular,{color:'warning'})}${Badge(t.notice,{color:'danger'})}</div><div class="jy-row">${Badge('Primary',{variant:'fill'})}${Badge('Weak')}${Badge('Large',{size:'large'})}</div>`;break;
 case 'button':h=v.includes('size')?`<div class="jy-row">${['small','medium','large','xlarge'].map(s=>btn(s,{size:s})).join('')}</div>`:v.includes('display')?`<div class="jy-stack">${['inline','block','full'].map(s=>btn(s,{display:s})).join('')}</div>`:`${btn(t.explore,{display:'block',variant:v.includes('outlined')?'outlined':v.includes('weak')?'weak':'fill',leadingIcon:v.includes('icon')?'pin':undefined,loading:v.includes('loading'),disabled:v.includes('disable')})}<div class="jy-row">${btn(t.save,{variant:'weak',loading:v.includes('loading'),disabled:v.includes('disable')})}${btn(t.cancel,{color:'dark',variant:'weak',disabled:v.includes('disable')})}${btn(t.remove,{color:'danger',variant:v.includes('weak')?'weak':'fill',size:'small',action:'confirm',disabled:v.includes('disable')})}</div>`;break;
 case 'board-row':h=[t.faq,t.select].map((s,i)=>`<details class="jy-board" ${v.includes('initial')&&i===0?'open':''}><summary>${s}${icon('down')}</summary><div>${t.faqAnswer}</div></details>`).join('');break;
 case 'border':h=`<p class="jy-body">${t.seongsan}</p><hr class="jy-line ${v.includes('padding')?'inset':v.includes('height')?'section':''}"><p class="jy-body">${t.aewol}</p><hr class="jy-line inset"><p class="jy-small jy-muted">Inset · 24px</p><hr class="jy-line section"><p class="jy-small jy-muted">Section · 16px</p>`;break;
 case 'bottom-info':h=`${listrow(t.date,t.dateValue,'map')}<div class="jy-info ${v.includes('none')?'':'gradient'}">${icon('info',16)} ${t.tip}<br>${t.description}</div>`;break;
 case 'bottom-sheet':case 'use-bottom-sheet':h=`<div class="jy-result"><span class="jy-asset large">${icon('layers',32)}</span><h2 class="jy-title">${t.select}</h2><p class="jy-muted">${t.description}</p></div>${btn(t.select,{display:'block',action:'sheet'})}`;break;
 case 'bubble':h=`<div class="jy-stack"><div class="jy-bubble ${v.includes('notail')?'notail':''}">${t.chat}</div><div class="jy-bubble mine ${v.includes('notail')?'notail':''}">${t.chatReply}</div><div class="jy-bubble">${t.tip}</div></div>`;break;
 case 'checkbox':h=`${Checkbox(t.required,{checked:true,radio:v.includes('radio')})}${Checkbox(t.privacy,{radio:v.includes('radio')})}${Checkbox(t.optional,{disabled:v.includes('disable'),radio:v.includes('radio')})}${Checkbox(t.optional,{disabled:true})}`;break;
 case 'grid-list':h=`<div class="jy-grid" style="--columns:${v.includes('column1')?1:v.includes('column3')?3:2}">${[t.seongsan,t.aewol,t.forest,t.south].map((s,i)=>`<button class="jy-griditem" data-action="place"><span class="jy-asset">${icon(['sun','map','pin','heart'][i],24)}</span><strong>${s}</strong><span class="jy-small jy-muted">${t.jeju} · ${t.place}</span></button>`).join('')}</div>`;break;
 case 'highlight':h=`<p class="jy-body">${t.trip}<br><mark class="jy-highlight">${t.seongsan}</mark></p><div class="jy-previewnote">${t.tip}</div>`;break;
 case 'icon-button':h=`<div class="jy-row">${['search','heart','bell','settings'].map((x,i)=>`<button type="button" class="jy-iconbtn ${v.includes('border')?'border':v.includes('fill')?'fill':i%2?'fill':''}" aria-label="${[t.search,t.save,t.push,t.more][i]}" data-action="${i===1?'favorite':'save'}" ${i===1?'aria-pressed="false"':''}>${icon(x,24)}</button>`).join('')}</div>`;break;
 case 'list-footer':h=`${listrow(t.seongsan,t.east)}${listrow(t.aewol,t.west)}<button class="jy-footerbutton" data-action="load-more">${t.more} ${icon('down',16)}</button>`;break;
 case 'list-header':h=`<div class="jy-between"><h2 class="jy-title">${t.place}</h2><button class="jy-textbtn" data-action="save">${t.more}${icon('arrow',16)}</button></div>${listrow(t.seongsan,t.east)}${listrow(t.aewol,t.west)}`;break;
 case 'loader':h=`<div class="jy-row" role="status" aria-label="${t.loading}"><span class="jy-loader small" aria-hidden="true"></span><span class="jy-loader" aria-hidden="true"></span><span class="jy-loader large" aria-hidden="true"></span><span class="jy-small jy-muted">${t.loading}</span></div>`;break;
 case 'menu':h=`<div class="jy-between"><h2 class="jy-title">${t.place}</h2><div class="jy-menuwrap"><button class="jy-textbtn" data-action="menu" aria-expanded="false">${t.sort}${icon('down',16)}</button><div class="jy-menupanel" role="menu">${[t.sort,t.sort2,t.sort3].map((s,i)=>`<button role="menuitem" data-action="menu-item">${icon(i?'pin':'check',16)}${s}</button>`).join('')}</div></div></div>${listrow(t.seongsan,t.east)}`;break;
 case 'modal':case 'dialog':case 'alert-dialog':case 'confirm-dialog':case 'use-dialog':h=`<div class="jy-result"><span class="jy-asset large">${icon(id==='confirm-dialog'?'info':'check',32)}</span><h2 class="jy-title">${id==='confirm-dialog'?t.remove:t.notice}</h2><p class="jy-muted">${t.description}</p></div>${btn(id==='confirm-dialog'?t.remove:t.notice,{display:'block',action:id==='confirm-dialog'?'confirm':'dialog'})}`;break;
 case 'numeric-spinner':h=`<div class="jy-between"><strong>${t.people}</strong><div class="jy-spinner"><button data-action="minus" aria-label="${lang==='ko'?'인원 줄이기':lang==='zh'?'减少人数':'Fewer travelers'}" ${v.includes('disable')?'disabled':''}>${icon('minus',16)}</button><input type="number" value="2" min="1" max="10" aria-label="${t.people}" ${v.includes('disable')?'disabled':''}><button data-action="plus" aria-label="${lang==='ko'?'인원 늘리기':lang==='zh'?'增加人数':'More travelers'}" ${v.includes('disable')?'disabled':''}>${icon('plus',16)}</button></div></div>`;break;
 case 'paragraph':h=`<p class="jy-body">${t.description}</p><p class="jy-body">${icon('pin',20)} ${t.seongsan} ${Badge(t.popular)}</p><a class="jy-textbtn" href="https://www.visitjeju.net/" target="_blank" rel="noopener">${t.read} ${icon('external',16)}</a>`;break;
 case 'post':h=`<article class="jy-post"><h2>${t.trip}</h2><p>${t.description}</p><h3>${t.explore}</h3><ul><li>${t.seongsan}</li><li>${t.aewol}</li><li>${t.forest}</li></ul><hr class="jy-line"><p>${t.tip}</p></article>`;break;
 case 'progress-bar':h=`<div class="jy-between"><strong>${t.step2}</strong><span class="jy-small jy-muted" data-progress-label>64%</span></div><div class="jy-progress ${v.includes('size')?'large':''}" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="64" aria-label="${t.step2}"><span></span></div><input type="range" class="jy-range" value="64" min="0" max="100" data-action="progress" aria-label="${t.step2}">`;break;
 case 'progress-stepper':h=`<div class="jy-progresssteps">${[t.step1,t.step2,t.step3].map((s,i)=>`<div ${i===1?'aria-current="step"':''}><span class="jy-stepdot ${i<2?'active':''}">${i===0?icon('check',16):i+1}</span>${v.includes('withouttitle')?'':s}</div>`).join('')}</div>${btn(t.next,{display:'block',action:'step-next'})}`;break;
 case 'rating':h=`<div class="jy-stars" role="group" aria-label="${lang==='ko'?'별점':lang==='zh'?'评分':'Rating'}">${[1,2,3,4,5].map(i=>`<button class="${i<=4?'selected':''}" aria-label="${i} / 5" aria-pressed="${i===4}" data-action="rate" data-value="${i}" ${v.includes('readonly')||v.includes('disable')?'disabled':''} ${v.includes('disable')?'aria-disabled="true"':''}>${icon('star',v.includes('size')?32:24)}</button>`).join('')}</div><span class="jy-muted jy-small" data-rating-label>4 / 5</span>`;break;
 case 'result':h=`<div class="jy-result" role="status"><span class="jy-asset large">${icon('check',40)}</span><h2 class="jy-title">${t.complete}</h2><p class="jy-muted">${t.completeDesc}</p>${btn(t.explore,{display:'block'})}</div>`;break;
 case 'search-field':h=`<label class="jy-search">${icon('search')}<input type="search" class="jy-input" placeholder="${t.search}" aria-label="${t.search}" data-action="search"><button class="jy-iconbtn" data-action="clear-search" aria-label="${t.reset}">${icon('close',16)}</button></label><div data-search-results>${listrow(t.seongsan,t.east)}${listrow(t.aewol,t.west)}${listrow(t.forest,t.east)}</div>`;break;
 case 'segmented-control':h=segment(t);break;
 case 'skeleton':h=`<div role="status" aria-label="${t.loading}" class="jy-stack">${[0,1,2].map(()=>`<div class="jy-row" style="flex-wrap:nowrap;gap:16px"><div class="jy-skeleton" style="width:56px;height:56px;flex-shrink:0;border-radius:16px"></div><div class="jy-stack" style="width:100%;gap:8px"><div class="jy-skeleton" style="width:72%"></div><div class="jy-skeleton" style="width:48%;height:13px;min-height:13px"></div></div></div>`).join('')}<span class="jy-small jy-muted">${t.loading}</span></div>`;break;
 case 'slider':if(v==='range'){h=renderExtra('range-slider',{lang,variant});break}h=`<div class="jy-between"><strong>${t.amount}</strong><output data-range-output>120,000</output></div><input class="jy-range" type="range" min="0" max="300000" step="10000" value="120000" aria-label="${t.amount}" data-action="range"><div class="jy-between jy-muted jy-small"><span>0</span><span>300,000</span></div>`;break;
 case 'stepper':h=`<div class="jy-stepper">${[t.step1,t.step2,t.step3].map((s,i)=>`<div><span class="jy-stepdot ${i<2?'active':''}">${i===0?icon('check',16):i+1}</span><p><strong>${s}</strong><br><span class="jy-small jy-muted">${[t.select,t.dateValue,t.completeDesc][i]}</span></p></div>`).join('')}</div>`;break;
 case 'switch':h=`${Switch(t.push,{checked:!v.includes('state'),disabled:v.includes('disable')})}${Switch(t.optional,{checked:false})}${Switch(t.optional,{checked:true,disabled:true})}`;break;
 case 'tab':h=v==='expanded'?renderExtra('expanded-tab-list',{lang,variant:'Expanded'}):segment(t,true);break;
 case 'table-row':h=`${[[t.date,t.dateValue],[t.people,'2'],[t.amount,t.value]].map(([a,b])=>`<div class="jy-table"><span>${a}</span><strong ${v.includes('left')?'style="text-align:left"':''}>${b}</strong></div>`).join('')}`;break;
 case 'text-button':h=`<div class="jy-row">${['clear','arrow','underline'].map(x=>`<button class="jy-textbtn" data-variant="${x}" data-action="save" ${v.includes('disable')?'disabled':''}>${t.more}${x==='arrow'?icon('arrow',16):''}</button>`).join('')}</div>`;break;
 case 'toast':case 'use-toast':h=`${btn(t.save,{display:'block',action:'toast'})}<div class="jy-previewnote">${icon('check',16)} ${t.saved}</div>`;break;
 case 'tooltip':h=`<div class="jy-tooltipbox"><div class="jy-tooltip" id="demo-tooltip" role="tooltip">${t.tip}</div><button class="jy-iconbtn fill" data-action="tooltip" aria-label="${t.notice}" aria-describedby="demo-tooltip" aria-expanded="true">${icon('info',24)}</button></div>`;break;
 case 'top':h=`<div class="jy-top">${Badge(t.jeju)}<h2>${t.trip}</h2><p>${t.description}</p>${btn(t.explore,{variant:'weak'})}</div>`;break;
 case 'v3':case 'v4':h=`<div data-agreement><div class="jy-card" style="padding:8px 16px">${Checkbox(t.agree,{checked:false})}</div>${Checkbox(t.required)}${Checkbox(t.privacy)}${Checkbox(t.optional)}<p class="jy-help" data-agreement-count>0 / 3</p></div>`;break;
 case 'asset-overview':case 'frame':case 'asset':h=`<div class="jy-row" style="gap:16px"><span class="jy-asset large">${icon('pin',40)}</span><span class="jy-asset">${icon('heart',24)}</span><span class="jy-asset" style="border-radius:50%;background:var(--jy-success-weak);color:var(--jy-success)">${icon('map',24)}</span><span class="jy-asset" style="font-weight:700">JY</span></div><p class="jy-small jy-muted">SVG · Text · Frame · 48 / 80px</p>${listrow(t.seongsan,t.east)}`;break;
 case 'bottom-cta-overview':case 'Single':case 'Double':case 'fixed-bottom-cta':h=`<div class="jy-top"><h2>${t.trip}</h2><p>${t.description}</p></div><div class="jy-cta">${v.includes('accessory')?`<p class="jy-info">${t.tip}</p>`:''}<div class="jy-row" style="flex-wrap:nowrap">${id==='Double'||v==='double'?btn(t.cancel,{variant:'weak'}):''}${btn(t.next,{display:'block'})}</div></div>`;break;
 case 'bar-chart':h=`<div class="jy-between"><strong>${t.amount}</strong><span class="jy-small jy-muted">KRW</span></div><div class="jy-chart" role="img" aria-label="${t.amount}: 40,000 / 65,000 / 50,000 / 80,000 / 120,000">${[32,54,42,67,100].map((n,i)=>`<div class="jy-barcol"><span>${new Intl.NumberFormat(lang,{notation:'compact',maximumFractionDigits:1}).format([40000,65000,50000,80000,120000][i])}</span><div class="jy-bar" style="--height:${n}%"></div><span>${i+1}</span></div>`).join('')}</div>`;break;
 case 'alphabet-keypad':case 'number-keypad':case 'full-secure-keypad':{let ks=id==='alphabet-keypad'?'ABCDEFGHIJKLMNO'.split(''):[1,2,3,4,5,6,7,8,9,'',0,'⌫'];h=`<label class="jy-small jy-muted">${t.key}</label><output class="jy-keydisplay" data-key-output aria-live="polite">—</output><div class="jy-keypad ${id==='alphabet-keypad'?'alpha':''}">${ks.map(s=>s===''?'<span></span>':`<button type="button" data-action="key" data-value="${s}" ${s==='⌫'?`aria-label="${t.reset}"`:''}>${s==='⌫'?icon('backspace',24):s}</button>`).join('')}</div>${id==='full-secure-keypad'?`<p class="jy-help">${t.warning}</p>`:''}`;break;}
 case 'list-row-overview':case 'list-row-components':case 'list-row-legacy':h=`${listrow(t.seongsan,t.east,'pin',Badge(t.popular))}${listrow(t.aewol,t.west,'map')}${listrow(t.forest,t.east,'heart')}`;break;
 case 'text-field':h=`${TextField(t.name,{placeholder:t.namePlaceholder,error:v.includes('error')?t.error:'',disabled:v.includes('disable')})}${v.includes('password')?`<label class="jy-field"><span class="jy-label">Password</span><input type="password" class="jy-input" autocomplete="new-password"></label>`:TextField(t.name,{value:'Jejuyeora',disabled:true})}`;break;
 case 'split-text-field':h=`<fieldset style="border:0;padding:0;margin:0"><legend class="jy-label" style="margin-bottom:8px">${t.key}</legend><div class="jy-split"><input class="jy-input" inputmode="numeric" maxlength="6" aria-label="${t.key} 1" placeholder="000000"><span>−</span><input class="jy-input" inputmode="numeric" maxlength="7" type="${v.includes('mask')?'password':'text'}" aria-label="${t.key} 2" placeholder="0000000"></div></fieldset>`;break;
 case 'text-area':h=`<label class="jy-field"><span class="jy-label">${t.message}</span><textarea class="jy-textarea" rows="5" maxlength="200" placeholder="${t.message}" data-action="textarea" ${v==='disabled'?'disabled':''} ${v==='error'?'aria-invalid="true" aria-describedby="textarea-error"':''}></textarea><span class="jy-help" data-textarea-count>0 / 200</span>${v==='error'?`<span class="jy-help jy-error" id="textarea-error">${t.error}</span>`:''}</label>`;break;
 case 'overlay-overview':h=`<div class="jy-row">${btn('Dialog',{action:'dialog',variant:'weak'})}${btn('Toast',{action:'toast',variant:'weak'})}${btn('Bottom Sheet',{action:'sheet',variant:'weak'})}</div><div class="jy-previewnote">${t.tip}</div>`;break;
 default:h=renderExtra(id,{lang,variant});
 }
 if(id==='text-field'&&['outlined','underlined'].includes(v))h=h.replace('class="jy-input"',`class="jy-input ${v}"`);
 if(id==='checkbox'&&v==='indeterminate')h=h.replace('<input','<input data-indeterminate aria-checked="mixed"');
 if(id==='checkbox'&&v==='error')h=h.replace('<input','<input aria-invalid="true"')+`<span class="jy-help jy-error">${t.error}</span>`;
 if(id==='fixed-bottom-cta')h=`<div class="jy-fixed-demo"><div class="jy-stack" style="padding:16px 0">${h.split('<div class="jy-cta">')[0]}${[t.seongsan,t.aewol,t.forest,t.south].map(x=>listrow(x,t.description)).join('')}</div><div class="jy-cta jy-sticky-cta">${Button(t.next,{display:'block'})}</div></div>`;
 return `<div class="jy-stack jy-demo" data-component="${id}" lang="${lang}" data-lang="${lang}">${h}</div>`;
}
let toastTimer;
export function useToast(message,{duration=2800}={}){document.querySelector('.jy-toast')?.remove();clearTimeout(toastTimer);const el=document.createElement('div');el.className='jy-toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.innerHTML=icon('check',18)+`<span>${escapeHTML(message)}</span>`;document.body.append(el);const dismiss=()=>el.remove();toastTimer=setTimeout(dismiss,duration);return {dismiss};}
export function useDialog({title='',description='',confirmLabel='확인',cancelLabel,lang='ko',onConfirm}={}){return new Promise(resolve=>{const dlg=document.createElement('dialog');dlg.className='jy-overlay';dlg.lang=lang;const titleId='jy-dialog-title';dlg.setAttribute('aria-labelledby',titleId);dlg.innerHTML=`<div class="jy-overlayinner"><h2 id="${titleId}">${escapeHTML(title)}</h2><p>${escapeHTML(description)}</p><div class="jy-row" style="flex-wrap:nowrap">${cancelLabel?Button(cancelLabel,{variant:'weak',action:'overlay-cancel'}):''}${Button(confirmLabel,{display:'block',action:'overlay-confirm'})}</div></div>`;document.body.append(dlg);const finish=value=>{if(value)onConfirm?.();dlg.close();resolve(value)};dlg.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='overlay-confirm')finish(true);if(a==='overlay-cancel'||e.target===dlg)finish(false)});dlg.addEventListener('close',()=>{resolve(false);dlg.remove()},{once:true});dlg.showModal()});}
export function useBottomSheet({title='',description='',options=[],lang='ko',onSelect}={}){const dlg=document.createElement('dialog');dlg.className='jy-overlay sheet';dlg.lang=lang;dlg.setAttribute('aria-label',title);dlg.innerHTML=`<div class="jy-handle"></div><div class="jy-overlayinner"><div class="jy-between"><h2>${escapeHTML(title)}</h2><button class="jy-iconbtn" aria-label="${strings[lang]?.close||'Close'}" data-dismiss>${icon('close')}</button></div>${description?`<p>${escapeHTML(description)}</p>`:''}${options.map((s,i)=>`<button class="jy-listrow" data-option="${i}"><span class="jy-rowtext"><strong>${escapeHTML(s)}</strong></span>${icon('arrow')}</button>`).join('')}</div>`;document.body.append(dlg);dlg.addEventListener('click',e=>{const b=e.target.closest('[data-option]');if(b){onSelect?.(options[Number(b.dataset.option)]);dlg.close()}if(e.target===dlg||e.target.closest('[data-dismiss]'))dlg.close()});dlg.addEventListener('close',()=>dlg.remove(),{once:true});dlg.showModal();return {close:()=>dlg.close()};}
export function mountInteractions(root=document){
 root.querySelectorAll('[data-indeterminate]').forEach(input=>input.indeterminate=true);
 if(root.__jyMounted)return;root.__jyMounted=true;mountExtraInteractions(root);
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const wrap=b.closest('.jy-demo')||root;const t=strings[wrap.dataset?.lang||document.documentElement.lang]||strings.ko;const action=b.dataset.action;
  if(['save','toast','place'].includes(action))useToast(action==='place'?t.tip:t.saved);
  if(action==='dialog'||action==='confirm'){const yes=await useDialog({title:action==='confirm'?t.remove:t.notice,description:action==='confirm'?t.removeDesc:t.completeDesc,confirmLabel:t.confirm,cancelLabel:action==='confirm'?t.cancel:null,lang:wrap.dataset?.lang||document.documentElement.lang});if(yes)useToast(action==='confirm'?t.deleted:t.complete)}
  if(action==='sheet')useBottomSheet({title:t.select,options:[t.east,t.west,t.south],lang:wrap.dataset?.lang||document.documentElement.lang,onSelect:s=>useToast(s)});
  if(action==='favorite'){const pressed=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',pressed);b.style.color=pressed?'var(--jy-danger)':'';useToast(pressed?t.saved:t.deleted)}
  if(action==='select-tab'){b.parentElement.querySelectorAll('[role=tab]').forEach(x=>{x.setAttribute('aria-selected',x===b);x.tabIndex=x===b?0:-1});wrap.querySelector('[data-tab-result]').textContent=b.textContent}
  if(action==='plus'||action==='minus'){const input=b.parentElement.querySelector('input');input.value=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)+(action==='plus'?1:-1)));input.dispatchEvent(new Event('change',{bubbles:true}))}
  if(action==='rate'){b.parentElement.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',Number(x.dataset.value)<=Number(b.dataset.value));x.setAttribute('aria-pressed',x===b)});wrap.querySelector('[data-rating-label]').textContent=b.dataset.value+' / 5'}
  if(action==='menu'){const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);b.nextElementSibling.classList.toggle('open',open)}
  if(action==='menu-item'){const panel=b.parentElement;const trigger=panel.previousElementSibling;trigger.innerHTML=escapeHTML(b.textContent)+icon('down',16);trigger.setAttribute('aria-expanded','false');panel.classList.remove('open');trigger.focus()}
  if(action==='clear-search'){const input=b.parentElement.querySelector('input');input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()}
  if(action==='key'){const out=wrap.querySelector('[data-key-output]');let val=out.dataset.value||'';val=b.dataset.value==='⌫'?val.slice(0,-1):(val+b.dataset.value).slice(0,16);out.dataset.value=val;out.textContent=wrap.dataset.component==='full-secure-keypad'?'●'.repeat(val.length)||'—':val||'—'}
  if(action==='tooltip'){const tip=wrap.querySelector('[role=tooltip]');tip.hidden=!tip.hidden;b.setAttribute('aria-expanded',!tip.hidden)}
  if(action==='load-more'){b.insertAdjacentHTML('beforebegin',listrow(t.forest,t.east));b.disabled=true;b.textContent=t.complete}
  if(action==='step-next'){const steps=[...wrap.querySelectorAll('.jy-progresssteps>div')];let current=steps.findIndex(s=>s.getAttribute('aria-current')==='step');const n=Math.min(steps.length-1,current+1);steps.forEach((s,i)=>{s.removeAttribute('aria-current');s.querySelector('.jy-stepdot').classList.toggle('active',i<=n)});steps[n].setAttribute('aria-current','step');if(n===2){b.disabled=true;b.textContent=t.complete}}
 });
 root.addEventListener('input',e=>{const el=e.target;const wrap=el.closest('.jy-demo');if(!wrap)return;const a=el.dataset.action;if(a==='range')wrap.querySelector('[data-range-output]').textContent=Number(el.value).toLocaleString();if(a==='progress'){wrap.querySelector('.jy-progress').setAttribute('aria-valuenow',el.value);wrap.querySelector('.jy-progress span').style.setProperty('--value',el.value+'%');wrap.querySelector('[data-progress-label]').textContent=el.value+'%'}if(a==='textarea')wrap.querySelector('[data-textarea-count]').textContent=el.value.length+' / 200';if(a==='search')wrap.querySelectorAll('.jy-listrow').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(el.value.toLowerCase()))});
 root.addEventListener('change',e=>{const spinner=e.target.closest('.jy-spinner');if(spinner){const input=spinner.querySelector('input');input.value=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)||Number(input.min)));spinner.querySelector('[data-action=minus]').disabled=input.disabled||Number(input.value)<=Number(input.min);spinner.querySelector('[data-action=plus]').disabled=input.disabled||Number(input.value)>=Number(input.max)}const g=e.target.closest('[data-agreement]');if(!g)return;const boxes=[...g.querySelectorAll('input')];if(e.target===boxes[0])boxes.slice(1).forEach(x=>x.checked=boxes[0].checked);else boxes[0].checked=boxes.slice(1).every(x=>x.checked);boxes[0].indeterminate=boxes.slice(1).some(x=>x.checked)&&!boxes[0].checked;g.querySelector('[data-agreement-count]').textContent=boxes.slice(1).filter(x=>x.checked).length+' / 3'});
 root.addEventListener('keydown',e=>{const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')];let i=tabs.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click();tabs[i].focus()}if(e.key==='Escape'){root.querySelectorAll?.('.jy-menupanel.open').forEach(p=>{p.classList.remove('open');p.previousElementSibling.setAttribute('aria-expanded','false');p.previousElementSibling.focus()})}});
}
